  "package": "@astryxdesign/cli",
  "data": {
    "title": "Explore the CLI",
    "content": [
      {
        "type": "prose",
        "text": "The CLI is your reference for components, tokens, templates, and docs. For reliable invocation (especially with AI assistants), add this script to your package.json:"
      },
      {
        "type": "code",
        "lang": "json",
        "code": "\"scripts\": {\n  \"astryx\": \"node node_modules/@astryxdesign/cli/clients/cli/bin/astryx.mjs\"\n}",
        "label": "package.json"
      },
      {
        "type": "prose",
        "text": "Then discover what's available:"
      },
      {
        "type": "code",
        "lang": "bash",
        "code": "astryx component          # list all components\nastryx component Button   # props, usage, theming for Button\nastryx docs               # list all doc topics\nastryx template --list    # available page templates\nastryx docs tokens        # spacing, color, radius reference",
        "label": "Terminal"
      }
    ],
    "id": "explore-the-cli",
    "links": {
      "up": "astryx docs getting-started --index",
      "previous": "astryx docs getting-started example-apps"
    }
  },
